bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
docker exec "$cid" node --input-type=module -e '
import {readFileSync} from "node:fs";
const s=readFileSync("/opt/videobot/src/telegram/paidListingPublisher.mjs","utf8");
const before="      if (!Array.isArray(preview) || preview.length !== 2 ||\n          preview.some(m=>!Number.isSafeInteger(m?.message_id)||m.message_id<=0))\n        throw new Error(\x27free album acknowledgment invalid\x27);";
if(s.includes("media_group_id mismatch"))process.exit(82);
if(!s.includes(before))process.exit(81);
if(!s.includes("telegramApi(\x27sendMediaGroup\x27,free)")||!s.includes("telegramApi(\x27sendPaidMedia\x27,paid)"))process.exit(83);
process.exit(0);
'
echo VIDEO_PUBLISHER_SAFE_PATCH_ANCHOR=PASS
